        heap[i] = newVal;
        while (i != 0 && compare(i, parent(i)) < 0) {
            swap(i, parent(i));
            i = parent(i);
        }
    }

    public T getMin() {
        if (size == 0) {
            throw new NoSuchElementException("Heap is empty");
        }
        return at(0);
    }

    public T extractMin() {
        if (size == 0) {
            throw new NoSuchElementException("Heap is empty");
        }
        if (size == 1) {
            T root = at(0);
            heap[0] = null;
            size--;
            return root;
        }
        T root = at(0);
        heap[0] = heap[size - 1];
        heap[size - 1] = null;
        size--;
        heapify(0);
        return root;
    }

    public void deleteKey(int i) {
        if (i == size - 1) {
            heap[size - 1] = null;
            size--;
            return;
        }
        heap[i] = heap[size - 1];
        heap[size - 1] = null;
        size--;
        // The replacement element may need to move up or down.
        if (i > 0 && compare(i, parent(i)) < 0) {
            while (i != 0 && compare(i, parent(i)) < 0) {
                swap(i, parent(i));
                i = parent(i);
            }
        } else {
            heapify(i);
        }
    }

    private void heapify(int i) {
        int l = left(i);
        int r = right(i);
        int smallest = i;
        if (l < size && compare(l, smallest) < 0) smallest = l;
        if (r < size && compare(r, smallest) < 0) smallest = r;
        if (smallest != i) {
            swap(i, smallest);
            heapify(smallest);
        }
    }

    public void increaseKey(int i, T newVal) {
        heap[i] = newVal;
        heapify(i);
    }

    public void changeKey(int i, T newVal) {
        int cmp = comparator.compare(at(i), newVal);
        if (cmp == 0) return;
        if (cmp < 0) {
            increaseKey(i, newVal);
        } else {
            decreaseKey(i, newVal);
        }
    }

    public boolean isEmpty() {
        return size == 0;
    }

    public int size() {
        return size;
    }

    @Override
    public String toString() {
        if (size == 0) return "[]";
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < size; i++) {
            if (i > 0) sb.append(", ");
            sb.append(at(i));
        }
        return sb.append("]").toString();
    }
}

